// analyzer/typedDicts.ts:79
// Creates a new custom TypedDict "alternate syntax" factory class.
pub fn create_typed_dict_type(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    typed_dict_class: ClassType,
    arg_list: &[Arg],
    node_info: &AnalyzerNodeInfoAccessor,
) -> ClassType {
    let file_info = node_info.get_file_info(error_node);

    // TypedDict supports two different syntaxes:
    // Point2D = TypedDict('Point2D', {'x': int, 'y': int, 'label': str})
    // Point2D = TypedDict('Point2D', x=int, y=int, label=str)
    let mut class_name: Option<String> = None;
    if arg_list.is_empty() {
        evaluator.add_diagnostic(
            DiagnosticRule::reportCallIssue,
            &LocMessage::typed_dict_first_arg(),
            error_node,
            None,
        );
    } else {
        let name_arg = &arg_list[0];
        let string_list = name_arg.value_expression().and_then(StringListNode::cast);
        match string_list {
            Some(string_list) if name_arg.arg_category() == ArgCategory::Simple => {
                let mut joined = JsString::from("");
                for s in string_list.d().strings.borrow().iter() {
                    let value = match &s.get().d {
                        ParseNodeDetails::String(d) => &d.value,
                        ParseNodeDetails::FormatString(d) => &d.value,
                        _ => unreachable!("a string list holds string nodes"),
                    };
                    joined = joined.concat(value);
                }
                class_name = Some(joined.to_string_lossy());
            }
            _ => {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportArgumentType,
                    &LocMessage::typed_dict_first_arg(),
                    name_arg.value_expression().unwrap_or(error_node),
                    None,
                );
            }
        }
    }

    let effective_class_name = match &class_name {
        Some(name) if !name.is_empty() => name.clone(),
        _ => "TypedDict".to_string(),
    };
    let class_type = ClassType::create_instantiable(
        &effective_class_name,
        &get_class_full_name(error_node, &file_info.module_name, &effective_class_name),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::TypedDictClass | ClassTypeFlags::ValidTypeAliasClass,
        get_type_source_id(error_node),
        /* declaredMetaclass */ None,
        typed_dict_class.d().shared.get().effective_metaclass.get(),
        None,
    );
    Rc::make_mut(&mut *class_type
        .d()
        .shared
        .get()
        .base_classes
        .borrow_mut())
        .push(typed_dict_class.0);
    compute_mro_linearization(class_type);

    let class_fields = ClassType::get_symbol_table(class_type);
    class_fields.set(
        "__class__",
        Symbol::create_with_type(
            SymbolFlags::ClassMember | SymbolFlags::IgnoredForProtocolMatch,
            class_type.0,
            None,
        ),
    );

    let mut using_dict_syntax = false;
    if arg_list.len() < 2 {
        evaluator.add_diagnostic(
            DiagnosticRule::reportCallIssue,
            &LocMessage::typed_dict_second_arg_dict(),
            error_node,
            None,
        );
    } else {
        let entries_arg = &arg_list[1];

        if entries_arg.arg_category() == ArgCategory::Simple
            && let Some(entries_dict) = entries_arg
                .value_expression()
                .and_then(DictionaryNode::cast)
        {
            using_dict_syntax = true;

            get_typed_dict_fields_from_dict_syntax(
                evaluator,
                entries_dict,
                class_fields,
                /* isInline */ false,
                node_info,
            );
        } else if entries_arg.name().is_some() {
            let mut entry_set: JsSet<String> = JsSet::default();
            for entry in &arg_list[1..] {
                let (Some(entry_name), Some(entry_value_expression)) =
                    (entry.name(), entry.value_expression())
                else {
                    continue;
                };

                if entry_set.contains(&entry_name.d().value) {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::typed_dict_entry_unique(),
                        entry_value_expression,
                        None,
                    );
                    continue;
                }

                // Record names in a map to detect duplicates.
                entry_set.insert(entry_name.d().value.clone());

                let new_symbol = Symbol::new(SymbolFlags::InstanceMember);
                let details = VariableDeclarationDetails::default();
                details
                    .type_annotation_node
                    .set(Some(entry_value_expression));
                details.is_runtime_type_expression.set(Some(true));
                let declaration = Declaration::create(
                    DeclarationType::Variable,
                    entry_name.0,
                    file_info.file_uri,
                    convert_offsets_to_range(
                        entry_name.start.get(),
                        TextRange::get_end(&entry_value_expression),
                        file_info.lines,
                    ),
                    file_info.module_name.clone(),
                    false,
                    DeclarationDetails::Variable(details),
                );
                new_symbol.add_declaration(declaration);

                class_fields.set(&entry_name.d().value, new_symbol);
            }
        } else {
            evaluator.add_diagnostic(
                DiagnosticRule::reportArgumentType,
                &LocMessage::typed_dict_second_arg_dict(),
                error_node,
                None,
            );
        }
    }

    if using_dict_syntax {
        let args_to_consider = &arg_list[2..];
        let mut saw_closed_or_extra_items = false;

        for arg in args_to_consider {
            let arg_value_expression = arg.value_expression();
            let arg_name_value = arg.name().map(|name| name.d().value.as_str());
            if arg_name_value == Some("total") || arg_name_value == Some("closed") {
                let arg_name_value = arg_name_value.unwrap();
                let const_type = arg_value_expression
                    .and_then(ConstantNode::cast)
                    .map(|constant| constant.d().const_type.get());
                if !(const_type == Some(KeywordType::False)
                    || const_type == Some(KeywordType::True))
                {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::typed_dict_bool_param().format(&[("name", arg_name_value)]),
                        arg_value_expression.unwrap_or(error_node),
                        None,
                    );
                } else if arg_name_value == "total" && const_type == Some(KeywordType::False) {
                    let shared = class_type.d().shared.get();
                    shared
                        .flags
                        .set(shared.flags.get() | ClassTypeFlags::CanOmitDictValues);
                } else if arg_name_value == "closed" {
                    if const_type == Some(KeywordType::True) {
                        let shared = class_type.d().shared.get();
                        shared.flags.set(
                            shared.flags.get()
                                | ClassTypeFlags::TypedDictMarkedClosed
                                | ClassTypeFlags::TypedDictEffectivelyClosed,
                        );
                    }

                    if saw_closed_or_extra_items {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportGeneralTypeIssues,
                            &LocMessage::typed_dict_extra_items_closed(),
                            arg_value_expression.unwrap_or(error_node),
                            None,
                        );
                    }

                    saw_closed_or_extra_items = true;
                }
            } else if arg_name_value == Some("extra_items") {
                let shared = class_type.d().shared.get();
                shared.typed_dict_extra_items_expr.set(arg_value_expression);
                shared
                    .flags
                    .set(shared.flags.get() | ClassTypeFlags::TypedDictEffectivelyClosed);

                if saw_closed_or_extra_items {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::typed_dict_extra_items_closed(),
                        arg_value_expression.unwrap_or(error_node),
                        None,
                    );
                }

                saw_closed_or_extra_items = true;
            } else {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportCallIssue,
                    &LocMessage::typed_dict_extra_args(),
                    arg_value_expression.unwrap_or(error_node),
                    None,
                );
            }
        }
    }

    synthesize_typed_dict_class_methods(evaluator, error_node, class_type, node_info);

    // Validate that the assigned variable name is consistent with the provided name.
    if let Some(assignment) = error_node.parent.get().and_then(AssignmentNode::cast)
        && let Some(class_name) = class_name.as_deref().filter(|name| !name.is_empty())
    {
        let target = assignment.d().left_expr.get();
        let typed_dict_target = match TypeAnnotationNode::cast(target) {
            Some(annotation) => annotation.d().value_expr.get(),
            None => target,
        };

        if let Some(typed_dict_target) = NameNode::cast(typed_dict_target)
            && typed_dict_target.d().value != class_name
        {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_assigned_name().format(&[("name", class_name)]),
                typed_dict_target.0,
                None,
            );
        }
    }

    class_type
}

// analyzer/typedDicts.ts:279
// Creates a new anonymous TypedDict class from an inlined dict[{}] type annotation.
pub fn create_typed_dict_type_inlined(
    evaluator: &TypeEvaluator,
    dict_node: DictionaryNode,
    typed_dict_class: ClassType,
    node_info: &AnalyzerNodeInfoAccessor,
) -> ClassType {
    let file_info = node_info.get_file_info(dict_node.0);
    let class_name = "<TypedDict>";

    let class_type = ClassType::create_instantiable(
        class_name,
        &get_class_full_name(dict_node.0, &file_info.module_name, class_name),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::TypedDictClass,
        get_type_source_id(dict_node.0),
        /* declaredMetaclass */ None,
        typed_dict_class.d().shared.get().effective_metaclass.get(),
        None,
    );
    Rc::make_mut(&mut *class_type
        .d()
        .shared
        .get()
        .base_classes
        .borrow_mut())
        .push(typed_dict_class.0);
    compute_mro_linearization(class_type);

    get_typed_dict_fields_from_dict_syntax(
        evaluator,
        dict_node,
        ClassType::get_symbol_table(class_type),
        /* isInline */ true,
        node_info,
    );
    synthesize_typed_dict_class_methods(evaluator, dict_node.0, class_type, node_info);

    class_type
}

// analyzer/typedDicts.ts:313
/// Nested in the TS body: createDefaultTypeVar (:451), createGetMethod (:462), createPopMethods (:515), createSetDefaultMethod (:556), createDelItemMethod (:574), createUpdateMethod (:585).
pub fn synthesize_typed_dict_class_methods(
    evaluator: &TypeEvaluator,
    node: P<ParseNode>,
    class_type: ClassType,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    assert!(ClassType::is_typed_dict_class(class_type));

    // Synthesize a __new__ method.
    let new_type =
        FunctionType::create_synthesized_instance("__new__", FunctionTypeFlags::ConstructorMethod);
    FunctionType::add_param(
        new_type,
        &FunctionParam::create(
            ParamCategory::Simple,
            class_type.0,
            FunctionParamFlags::TypeDeclared,
            Some("cls"),
            None,
            None,
        ),
    );
    FunctionType::add_default_params(new_type, false);
    new_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(ClassType::clone_as_instance(class_type, true).0));
    let constructor_scope_id = get_type_var_scope_id(class_type.0);
    new_type
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = constructor_scope_id;

    // Synthesize an __init__ method with two overrides.
    let init_override1 =
        FunctionType::create_synthesized_instance("__init__", FunctionTypeFlags::Overloaded);
    FunctionType::add_param(
        init_override1,
        &FunctionParam::create(
            ParamCategory::Simple,
            ClassType::clone_as_instance(class_type, true).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );
    init_override1
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_none_type()));
    let constructor_scope_id = get_type_var_scope_id(class_type.0);
    init_override1
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = constructor_scope_id;

    // The first parameter must be positional-only.
    FunctionType::add_param(
        init_override1,
        &FunctionParam::create(
            ParamCategory::Simple,
            ClassType::clone_as_instance(class_type, true).0,
            FunctionParamFlags::TypeDeclared,
            Some("__map"),
            None,
            None,
        ),
    );

    let entries = get_typed_dict_members_for_class(evaluator, class_type, false);
    let entries_extra_items = entries.extra_items.borrow().clone();
    let extra_entries_info = match entries_extra_items.clone() {
        Some(extra_items) => extra_items,
        None => get_effective_extra_items_entry_type(evaluator, class_type),
    };
    // The entries are this function's own copy; nothing writes them below.
    let known_items: Vec<(String, TypedDictEntry)> = entries
        .known_items
        .borrow()
        .iter()
        .map(|(name, entry)| (name.clone(), entry.clone()))
        .collect();
    let mut all_entries_are_read_only = !known_items.is_empty();

    if !known_items.is_empty() {
        FunctionType::add_position_only_param_separator(init_override1);

        // All subsequent parameters must be named, so insert an empty "*".
        FunctionType::add_keyword_only_param_separator(init_override1);
    }

    let init_override2 =
        FunctionType::create_synthesized_instance("__init__", FunctionTypeFlags::Overloaded);
    FunctionType::add_param(
        init_override2,
        &FunctionParam::create(
            ParamCategory::Simple,
            ClassType::clone_as_instance(class_type, true).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );
    init_override2
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_none_type()));
    let constructor_scope_id = get_type_var_scope_id(class_type.0);
    init_override2
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = constructor_scope_id;

    if !known_items.is_empty() {
        // All parameters must be named, so insert an empty "*".
        FunctionType::add_keyword_only_param_separator(init_override2);
    }

    for (name, entry) in &known_items {
        FunctionType::add_param(
            init_override1,
            &FunctionParam::create(
                ParamCategory::Simple,
                entry.value_type,
                FunctionParamFlags::TypeDeclared,
                Some(name),
                Some(entry.value_type),
                None,
            ),
        );

        FunctionType::add_param(
            init_override2,
            &FunctionParam::create(
                ParamCategory::Simple,
                entry.value_type,
                FunctionParamFlags::TypeDeclared,
                Some(name),
                if entry.is_required {
                    None
                } else {
                    Some(entry.value_type)
                },
                None,
            ),
        );

        if !entry.is_read_only {
            all_entries_are_read_only = false;
        }
    }

    if let Some(extra_items) = &entries_extra_items
        && !is_never(extra_items.value_type)
    {
        FunctionType::add_param(
            init_override1,
            &FunctionParam::create(
                ParamCategory::KwargsDict,
                extra_items.value_type,
                FunctionParamFlags::TypeDeclared,
                Some("kwargs"),
                None,
                None,
            ),
        );

        FunctionType::add_param(
            init_override2,
            &FunctionParam::create(
                ParamCategory::KwargsDict,
                extra_items.value_type,
                FunctionParamFlags::TypeDeclared,
                Some("kwargs"),
                None,
                None,
            ),
        );
    }

    let symbol_table = ClassType::get_symbol_table(class_type);
    let init_type = OverloadedType::create(&[init_override1, init_override2], None);
    symbol_table.set(
        "__init__",
        Symbol::create_with_type(SymbolFlags::ClassMember, init_type.0, None),
    );
    symbol_table.set(
        "__new__",
        Symbol::create_with_type(SymbolFlags::ClassMember, new_type.0, None),
    );

    let str_class = evaluator.get_built_in_type(node, "str");

    // Synthesize a "get", pop, and setdefault method for each named entry.
    if is_instantiable_class(str_class) {
        let str_class_type = ClassType(str_class);
        let self_param = FunctionParam::create(
            ParamCategory::Simple,
            ClassType::clone_as_instance(class_type, true).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        );

        // analyzer/typedDicts.ts:451
        let create_default_type_var = |func: FunctionType| -> TypeVarType {
            let mut default_type_var =
                TypeVarType::create_instance("__TDefault", TypeVarKind::TypeVar);
            let func_scope_id = func
                .d()
                .shared
                .get()
                .type_var_scope_id
                .borrow()
                .clone()
                .unwrap();
            default_type_var = TypeVarType::clone_for_scope_id(
                default_type_var,
                func_scope_id,
                Some(class_type.d().shared.get().name.clone()),
                Some(TypeVarScopeType::Function),
            );
            default_type_var
        };

        // analyzer/typedDicts.ts:462
        // TS defaults: isEntryRequired = false, defaultTypeMatchesField = false.
        let create_get_method = |key_type: P<Type>,
                                 value_type: P<Type>,
                                 include_default: bool,
                                 is_entry_required: bool,
                                 default_type_matches_field: bool|
         -> FunctionType {
            let get_overload =
                FunctionType::create_synthesized_instance("get", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(get_overload, &self_param);
            let scope_id = get_scope_id_for_node(node, node_info.reader());
            *get_overload.d().shared.get().type_var_scope_id.borrow_mut() = Some(scope_id);
            FunctionType::add_param(
                get_overload,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    key_type,
                    FunctionParamFlags::TypeDeclared,
                    Some("k"),
                    None,
                    None,
                ),
            );

            if include_default {
                let default_type_var = create_default_type_var(get_overload);
                let default_param_type: P<Type>;
                let return_type: P<Type>;

                if is_entry_required {
                    // If the entry is required, the type of the default param doesn't matter
                    // because the type will always come from the value.
                    default_param_type = AnyType::create(false).0;
                    return_type = value_type;
                } else {
                    if default_type_matches_field {
                        default_param_type = value_type;
                    } else {
                        default_param_type = combine_types(&[value_type, default_type_var.0], None);
                    }

                    return_type = default_param_type;
                }

                FunctionType::add_param(
                    get_overload,
                    &FunctionParam::create(
                        ParamCategory::Simple,
                        default_param_type,
                        FunctionParamFlags::TypeDeclared,
                        Some("default"),
                        None,
                        None,
                    ),
                );
                get_overload
                    .d()
                    .shared
                    .get()
                    .declared_return_type
                    .set(Some(return_type));
            } else {
                let return_type = if is_entry_required {
                    value_type
                } else {
                    combine_types(&[value_type, evaluator.get_none_type()], None)
                };
                get_overload
                    .d()
                    .shared
                    .get()
                    .declared_return_type
                    .set(Some(return_type));
            }
            get_overload
        };

        // analyzer/typedDicts.ts:515
        let create_pop_methods = |key_type: P<Type>,
                                  value_type: P<Type>,
                                  is_entry_required: bool|
         -> Vec<FunctionType> {
            let key_param = FunctionParam::create(
                ParamCategory::Simple,
                key_type,
                FunctionParamFlags::TypeDeclared,
                Some("k"),
                None,
                None,
            );

            let pop_overload1 =
                FunctionType::create_synthesized_instance("pop", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(pop_overload1, &self_param);
            FunctionType::add_param(pop_overload1, &key_param);
            pop_overload1
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(value_type));

            let pop_overload2 =
                FunctionType::create_synthesized_instance("pop", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(pop_overload2, &self_param);
            FunctionType::add_param(pop_overload2, &key_param);
            let scope_id = get_scope_id_for_node(node, node_info.reader());
            *pop_overload2
                .d()
                .shared
                .get()
                .type_var_scope_id
                .borrow_mut() = Some(scope_id);
            let default_type_var = create_default_type_var(pop_overload2);

            let default_param_type: P<Type>;
            let return_type: P<Type>;

            if is_entry_required {
                // If the entry is required, the type of the default param doesn't matter
                // because the type will always come from the value.
                default_param_type = AnyType::create(false).0;
                return_type = value_type;
            } else {
                default_param_type = combine_types(&[value_type, default_type_var.0], None);
                return_type = default_param_type;
            }

            FunctionType::add_param(
                pop_overload2,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    default_param_type,
                    FunctionParamFlags::TypeDeclared,
                    Some("default"),
                    Some(default_param_type),
                    None,
                ),
            );
            pop_overload2
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(return_type));
            vec![pop_overload1, pop_overload2]
        };

        // analyzer/typedDicts.ts:556
        let create_set_default_method = |key_type: P<Type>, value_type: P<Type>| -> FunctionType {
            let set_default_overload = FunctionType::create_synthesized_instance(
                "setdefault",
                FunctionTypeFlags::Overloaded,
            );
            FunctionType::add_param(set_default_overload, &self_param);
            FunctionType::add_param(
                set_default_overload,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    key_type,
                    FunctionParamFlags::TypeDeclared,
                    Some("k"),
                    None,
                    None,
                ),
            );
            FunctionType::add_param(
                set_default_overload,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    value_type,
                    FunctionParamFlags::TypeDeclared,
                    Some("default"),
                    None,
                    None,
                ),
            );
            set_default_overload
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(value_type));
            set_default_overload
        };

        // analyzer/typedDicts.ts:574
        let create_del_item_method = |key_type: P<Type>| -> FunctionType {
            let del_item_overload =
                FunctionType::create_synthesized_instance("delitem", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(del_item_overload, &self_param);
            FunctionType::add_param(
                del_item_overload,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    key_type,
                    FunctionParamFlags::TypeDeclared,
                    Some("k"),
                    None,
                    None,
                ),
            );
            del_item_overload
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(evaluator.get_none_type()));
            del_item_overload
        };

        // analyzer/typedDicts.ts:585
        let create_update_method = || -> OverloadedType {
            // Overload 1: update(__m: Partial[<writable fields>], /)
            let update_method1 =
                FunctionType::create_synthesized_instance("update", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(update_method1, &self_param);

            // Overload 2: update(__m: Iterable[tuple[<name>, <type>]], /)
            let update_method2 =
                FunctionType::create_synthesized_instance("update", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(update_method2, &self_param);

            // Overload 3: update(*, <name>: <type>, ...)
            let update_method3 =
                FunctionType::create_synthesized_instance("update", FunctionTypeFlags::Overloaded);
            FunctionType::add_param(update_method3, &self_param);

            // If all entries are read-only, don't allow updates.
            FunctionType::add_param(
                update_method1,
                &FunctionParam::create(
                    ParamCategory::Simple,
                    if all_entries_are_read_only {
                        NeverType::create_never().0
                    } else {
                        ClassType::clone_as_instance(
                            ClassType::clone_for_partial_typed_dict(class_type),
                            true,
                        )
                        .0
                    },
                    FunctionParamFlags::TypeDeclared,
                    Some("__m"),
                    None,
                    None,
                ),
            );

            if !known_items.is_empty() {
                FunctionType::add_position_only_param_separator(update_method1);
                FunctionType::add_keyword_only_param_separator(update_method3);
            }

            update_method1
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(evaluator.get_none_type()));
            update_method2
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(evaluator.get_none_type()));
            update_method3
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(evaluator.get_none_type()));

            let mut tuples_to_combine: Vec<P<Type>> = vec![];
            let tuple_class = evaluator.get_built_in_type(node, "tuple");

            for (name, entry) in &known_items {
                if !entry.is_read_only {
                    // For writable entries, add a tuple entry.
                    if is_instantiable_class(tuple_class) && is_instantiable_class(str_class) {
                        let tuple_type = specialize_tuple_class(
                            ClassType::clone_as_instance(ClassType(tuple_class), true),
                            &[
                                TupleTypeArg {
                                    type_: ClassType::clone_with_literal(
                                        ClassType::clone_as_instance(str_class_type, true),
                                        Some(LiteralValue::String(name.into())),
                                    )
                                    .0,
                                    is_unbounded: false,
                                    is_optional: None,
                                },
                                TupleTypeArg {
                                    type_: entry.value_type,
                                    is_unbounded: false,
                                    is_optional: None,
                                },
                            ],
                            true,
                            false,
                        );

                        tuples_to_combine.push(tuple_type.0);
                    }

                    // For writable entries, add a keyword argument.
                    FunctionType::add_param(
                        update_method3,
                        &FunctionParam::create(
                            ParamCategory::Simple,
                            entry.value_type,
                            FunctionParamFlags::TypeDeclared,
                            Some(name),
                            Some(AnyType::create(/* isEllipsis */ true).0),
                            None,
                        ),
                    );
                }
            }

            let iterable_class = evaluator.get_typing_type(node, "Iterable");
            if let Some(iterable_class) = iterable_class
                && is_instantiable_class(iterable_class)
            {
                let iterable_type = ClassType::clone_as_instance(ClassType(iterable_class), true);

                FunctionType::add_param(
                    update_method2,
                    &FunctionParam::create(
                        ParamCategory::Simple,
                        ClassType::specialize(
                            iterable_type,
                            Some(&[combine_types(&tuples_to_combine, None)]),
                            None,
                            false,
                            None,
                            None,
                        )
                        .0,
                        FunctionParamFlags::TypeDeclared,
                        Some("__m"),
                        None,
                        None,
                    ),
                );
            }

            if !known_items.is_empty() {
                FunctionType::add_position_only_param_separator(update_method2);
            }

            // Note that the order of method1 and method2 is swapped. This is done so
            // the method1 signature is used in the error message when neither method2
            // or method1 match.
            OverloadedType::create(&[update_method2, update_method1, update_method3], None)
        };

        let mut get_overloads: Vec<FunctionType> = vec![];
        let mut pop_overloads: Vec<FunctionType> = vec![];
        let mut set_default_overloads: Vec<FunctionType> = vec![];

        for (name, entry) in &known_items {
            let name_literal_type = ClassType::clone_as_instance(
                ClassType::clone_with_literal(
                    str_class_type,
                    Some(LiteralValue::String(name.into())),
                ),
                true,
            );

            get_overloads.push(create_get_method(
                name_literal_type.0,
                entry.value_type,
                /* includeDefault */ false,
                entry.is_required,
                false,
            ));

            get_overloads.push(create_get_method(
                name_literal_type.0,
                entry.value_type,
                /* includeDefault */ true,
                /* isEntryRequired */ entry.is_required,
                /* defaultTypeMatchesField */ entry.is_required,
            ));

            // Add a pop method if the entry is not required.
            if !entry.is_required && !entry.is_read_only {
                pop_overloads.extend(create_pop_methods(
                    name_literal_type.0,
                    entry.value_type,
                    entry.is_required,
                ));
            }

            if !entry.is_read_only {
                set_default_overloads.push(create_set_default_method(
                    name_literal_type.0,
                    entry.value_type,
                ));
            }
        }

        let str_type = ClassType::clone_as_instance(str_class_type, true);

        // If the class is closed, we can assume that any other keys that
        // are present will return the default parameter value or the extra
        // entries value type.
        if ClassType::is_typed_dict_effectively_closed(class_type) {
            get_overloads.push(create_get_method(
                str_type.0,
                combine_types(
                    &[extra_entries_info.value_type, evaluator.get_none_type()],
                    None,
                ),
                /* includeDefault */ false,
                /* isEntryRequired */ true,
                false,
            ));
            get_overloads.push(create_get_method(
                str_type.0,
                extra_entries_info.value_type,
                /* includeDefault */ true,
                false,
                false,
            ));
        } else {
            // Provide a final `get` overload that handles the general case where
            // the key is a str but the literal value isn't known.
            get_overloads.push(create_get_method(
                str_type.0,
                AnyType::create(false).0,
                /* includeDefault */ false,
                false,
                false,
            ));
            get_overloads.push(create_get_method(
                str_type.0,
                AnyType::create(false).0,
                /* includeDefault */ true,
                false,
                false,
            ));
        }

        // Add a catch-all pop method.
        if ClassType::is_typed_dict_effectively_closed(class_type) {
            if !is_never(extra_entries_info.value_type) {
                pop_overloads.extend(create_pop_methods(
                    str_type.0,
                    extra_entries_info.value_type,
                    /* isEntryRequired */ false,
                ));
            }
        } else {
            pop_overloads.extend(create_pop_methods(
                str_type.0,
                evaluator.get_object_type(),
                /* isEntryRequired */ false,
            ));
        }

        symbol_table.set(
            "get",
            Symbol::create_with_type(
                SymbolFlags::ClassMember,
                OverloadedType::create(&get_overloads, None).0,
                None,
            ),
        );

        if !pop_overloads.is_empty() {
            symbol_table.set(
                "pop",
                Symbol::create_with_type(
                    SymbolFlags::ClassMember,
                    OverloadedType::create(&pop_overloads, None).0,
                    None,
                ),
            );
        }

        if !set_default_overloads.is_empty() {
            symbol_table.set(
                "setdefault",
                Symbol::create_with_type(
                    SymbolFlags::ClassMember,
                    OverloadedType::create(&set_default_overloads, None).0,
                    None,
                ),
            );
        }

        if !all_entries_are_read_only {
            symbol_table.set(
                "__delitem__",
                Symbol::create_with_type(
                    SymbolFlags::ClassMember,
                    create_del_item_method(str_type.0).0,
                    None,
                ),
            );
        }

        symbol_table.set(
            "update",
            Symbol::create_with_type(SymbolFlags::ClassMember, create_update_method().0, None),
        );

        // If the TypedDict is closed and all of its entries are NotRequired and
        // not ReadOnly, add a "clear" and "popitem" method.
        let dict_value_type = get_typed_dict_dict_equivalent(evaluator, class_type, 0);

        if let Some(dict_value_type) = dict_value_type {
            let clear_method =
                FunctionType::create_synthesized_instance("clear", FunctionTypeFlags::None);
            FunctionType::add_param(clear_method, &self_param);
            clear_method
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(evaluator.get_none_type()));
            symbol_table.set(
                "clear",
                Symbol::create_with_type(SymbolFlags::ClassMember, clear_method.0, None),
            );

            let pop_item_method =
                FunctionType::create_synthesized_instance("popitem", FunctionTypeFlags::None);
            FunctionType::add_param(pop_item_method, &self_param);
            let tuple_class_type = evaluator.get_tuple_class_type();

            let tuple_type: P<Type> = match tuple_class_type {
                Some(tuple_class_type) if is_instantiable_class(tuple_class_type.0) => {
                    specialize_tuple_class(
                        ClassType::clone_as_instance(tuple_class_type, true),
                        &[
                            TupleTypeArg {
                                type_: str_type.0,
                                is_unbounded: false,
                                is_optional: None,
                            },
                            TupleTypeArg {
                                type_: dict_value_type,
                                is_unbounded: false,
                                is_optional: None,
                            },
                        ],
                        /* isTypeArgExplicit */ true,
                        false,
                    )
                    .0
                }
                _ => UnknownType::create(false).0,
            };

            pop_item_method
                .d()
                .shared
                .get()
                .declared_return_type
                .set(Some(tuple_type));
            symbol_table.set(
                "popitem",
                Symbol::create_with_type(SymbolFlags::ClassMember, pop_item_method.0, None),
            );
        }

        // If the TypedDict is closed, we can provide a more accurate value type
        // for the "items", "keys" and "values" methods.
        let mapping_value_type = get_typed_dict_mapping_equivalent(evaluator, class_type);

        if let Some(mapping_value_type) = mapping_value_type {
            let mut key_value_type: P<Type> = str_type.0;

            // If we know that there can be no more items, we can provide
            // a more accurate key type consisting of all known keys.
            if let Some(extra_items) = &entries_extra_items
                && is_never(extra_items.value_type)
            {
                let key_types: Vec<P<Type>> = known_items
                    .iter()
                    .map(|(key, _)| {
                        ClassType::clone_with_literal(
                            str_type,
                            Some(LiteralValue::String(key.into())),
                        )
                        .0
                    })
                    .collect();
                key_value_type = combine_types(&key_types, None);
            }

            for method_name in ["items", "keys", "values"] {
                let method =
                    FunctionType::create_synthesized_instance(method_name, FunctionTypeFlags::None);
                FunctionType::add_param(method, &self_param);

                let return_type_class =
                    evaluator.get_typing_type(node, &format!("dict_{method_name}"));
                if let Some(return_type_class) = return_type_class
                    && is_instantiable_class(return_type_class)
                    && ClassType(return_type_class)
                        .d()
                        .shared
                        .get()
                        .type_params
                        .borrow()
                        .len()
                        == 2
                {
                    let return_type = ClassType::specialize(
                        ClassType::clone_as_instance(ClassType(return_type_class), true),
                        Some(&[key_value_type, mapping_value_type]),
                        None,
                        false,
                        None,
                        None,
                    );
                    method
                        .d()
                        .shared
                        .get()
                        .declared_return_type
                        .set(Some(return_type.0));

                    symbol_table.set(
                        method_name,
                        Symbol::create_with_type(SymbolFlags::ClassMember, method.0, None),
                    );
                }
            }
        }
    }
}

// analyzer/typedDicts.ts:831
/// TS defaults: allowNarrowed = false.
pub fn get_typed_dict_members_for_class(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    allow_narrowed: bool,
) -> P<TypedDictEntries> {
    // Were the entries already calculated and cached?
    if class_type
        .d()
        .shared
        .get()
        .typed_dict_entries
        .get()
        .is_none()
    {
        let entries = P::new_eval(TypedDictEntries {
            known_items: RefCell::new(JsMap::default()),
            extra_items: RefCell::new(None),
        });
        get_typed_dict_members_for_class_recursive(evaluator, class_type, entries, 0);

        if ClassType::is_typed_dict_marked_closed(class_type)
            && entries.extra_items.borrow().is_none()
        {
            *entries.extra_items.borrow_mut() = Some(TypedDictEntry {
                value_type: NeverType::create_never().0,
                is_read_only: false,
                is_required: false,
                is_provided: false,
            });
        }

        // Cache the entries for next time.
        class_type
            .d()
            .shared
            .get()
            .typed_dict_entries
            .set(Some(entries));
    }

    let solution = build_solution_from_specialized_class(class_type);
    let apply_options = ApplyTypeVarOptions::default();

    // Create a specialized copy of the entries so the caller can mutate them.
    let mut entries: JsMap<String, TypedDictEntry> = JsMap::default();
    let cached_known_items: Vec<(String, TypedDictEntry)> = class_type
        .d()
        .shared
        .get()
        .typed_dict_entries
        .get()
        .unwrap()
        .known_items
        .borrow()
        .iter()
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    for (key, value) in cached_known_items {
        let mut td_entry = value;
        td_entry.value_type =
            apply_solved_type_vars(td_entry.value_type, &solution, &apply_options);

        // If the class is "Partial", make all entries optional and convert all
        // read-only entries to Never.
        let is_typed_dict_partial = class_type.d().priv_.borrow().cold().is_typed_dict_partial;
        if is_typed_dict_partial == Some(true) {
            td_entry.is_required = false;

            if td_entry.is_read_only {
                td_entry.value_type = NeverType::create_never().0;
            } else {
                td_entry.is_read_only = true;
            }
        }

        entries.insert(key, td_entry);
    }

    // Apply narrowed types on top of existing entries if present.
    if allow_narrowed {
        let narrowed_entries = class_type
            .d()
            .priv_
            .borrow()
            .cold().typed_dict_narrowed_entries
            .clone();
        if let Some(narrowed_entries) = narrowed_entries {
            for (key, value) in narrowed_entries {
                let mut td_entry = value;
                td_entry.value_type =
                    apply_solved_type_vars(td_entry.value_type, &solution, &apply_options);
                entries.insert(key, td_entry);
            }
        }
    }

    let mut extra_items = class_type
        .d()
        .shared
        .get()
        .typed_dict_entries
        .get()
        .and_then(|cached| cached.extra_items.borrow().clone());
    if let Some(cached_extra_items) = extra_items {
        extra_items = Some(TypedDictEntry {
            value_type: apply_solved_type_vars(
                cached_extra_items.value_type,
                &solution,
                &apply_options,
            ),
            ..cached_extra_items
        });
    }

    P::new_eval(TypedDictEntries {
        known_items: RefCell::new(entries),
        extra_items: RefCell::new(extra_items),
    })
}

// analyzer/typedDicts.ts:902
// If the TypedDict class is consistent with Mapping[str, T] where T
// is some type other than object, it returns T. Otherwise it returns undefined.
pub fn get_typed_dict_mapping_equivalent(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
) -> Option<P<Type>> {
    assert!(is_instantiable_class(class_type.0));
    assert!(ClassType::is_typed_dict_class(class_type));

    // If the TypedDict class isn't closed, it's just a normal Mapping[str, object].
    if !ClassType::is_typed_dict_effectively_closed(class_type) {
        return None;
    }

    let entries = get_typed_dict_members_for_class(evaluator, class_type, false);
    let mut types_to_combine: Vec<P<Type>> = vec![];

    for entry in entries.known_items.borrow().values() {
        types_to_combine.push(entry.value_type);
    }

    if let Some(extra_items) = &*entries.extra_items.borrow() {
        types_to_combine.push(extra_items.value_type);
    }

    // Is the final value type 'object'?
    let value_type = combine_types(&types_to_combine, None);
    if is_class_instance(value_type)
        && ClassType::is_built_in(ClassType(value_type), Some(&["object"]))
    {
        return None;
    }

    Some(value_type)
}

// analyzer/typedDicts.ts:933
// If the TypedDict class is consistent with dict[str, T], it returns T.
// Otherwise it returns undefined.
/// TS defaults: recursionCount = 0.
pub fn get_typed_dict_dict_equivalent(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    recursion_count: u32,
) -> Option<P<Type>> {
    assert!(is_instantiable_class(class_type.0));
    assert!(ClassType::is_typed_dict_class(class_type));

    // If the TypedDict class isn't closed, it's not equivalent to a dict.
    if !ClassType::is_typed_dict_effectively_closed(class_type) {
        return None;
    }

    let entries = get_typed_dict_members_for_class(evaluator, class_type, false);

    // If there is no "extraItems" defined or it is read-only, it's not
    // equivalent to a dict.
    let extra_items = entries.extra_items.borrow().clone();
    let extra_items = match extra_items {
        Some(extra_items) if !extra_items.is_read_only => extra_items,
        _ => return None,
    };

    let mut dict_value_type = extra_items.value_type;

    let mut is_equivalent_to_dict = true;
    let known_items: Vec<TypedDictEntry> = entries.known_items.borrow().values().cloned().collect();
    for entry in known_items {
        if entry.is_read_only || entry.is_required {
            is_equivalent_to_dict = false;
        }

        dict_value_type = combine_types(&[dict_value_type, entry.value_type], None);

        if !evaluator.assign_type(
            dict_value_type,
            entry.value_type,
            /* diag */ None,
            /* constraints */ None,
            AssignTypeFlags::Invariant,
            recursion_count + 1,
        ) {
            is_equivalent_to_dict = false;
        }
    }

    if !is_equivalent_to_dict {
        return None;
    }

    Some(dict_value_type)
}

// analyzer/typedDicts.ts:985
pub(crate) fn get_typed_dict_fields_from_dict_syntax(
    evaluator: &TypeEvaluator,
    entry_dict: DictionaryNode,
    class_fields: SymbolTable,
    is_inline: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    let mut entry_set: JsSet<String> = JsSet::default();
    let file_info = node_info.get_file_info(entry_dict.0);

    let items = entry_dict.d().items.borrow().clone();
    for entry in items {
        let Some(entry) = DictionaryKeyEntryNode::cast(entry) else {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_second_arg_dict_entry(),
                entry,
                None,
            );
            continue;
        };

        let key_expr = entry.d().key_expr.get();
        let Some(key_string_list) = StringListNode::cast(key_expr) else {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_entry_name(),
                key_expr,
                None,
            );
            continue;
        };

        let mut joined = JsString::from("");
        for s in key_string_list.d().strings.borrow().iter() {
            let value = match &s.get().d {
                ParseNodeDetails::String(d) => &d.value,
                ParseNodeDetails::FormatString(d) => &d.value,
                _ => unreachable!("a string list holds string nodes"),
            };
            joined = joined.concat(value);
        }
        let entry_name = joined.to_string_lossy();
        if entry_name.is_empty() {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_empty_name(),
                key_expr,
                None,
            );
            continue;
        }

        if entry_set.contains(&entry_name) {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_entry_unique(),
                key_expr,
                None,
            );
            continue;
        }

        // Record names in a set to detect duplicates.
        entry_set.insert(entry_name.clone());

        let new_symbol = Symbol::new(SymbolFlags::InstanceMember);
        let details = VariableDeclarationDetails::default();
        details
            .type_annotation_node
            .set(Some(entry.d().value_expr.get()));
        details.is_runtime_type_expression.set(Some(!is_inline));
        let declaration = Declaration::create(
            DeclarationType::Variable,
            key_expr,
            file_info.file_uri,
            convert_offsets_to_range(
                key_expr.start.get(),
                TextRange::get_end(&key_expr),
                file_info.lines,
            ),
            file_info.module_name.clone(),
            false,
            DeclarationDetails::Variable(details),
        );
        declaration.is_in_inlined_typed_dict.set(Some(true));
        new_symbol.add_declaration(declaration);

        class_fields.set(&entry_name, new_symbol);
    }

    // Set the type in the type cache for the dict node so it doesn't
    // get evaluated again.
    evaluator.set_type_result_for_node(
        entry_dict.0,
        P::new_eval(TypeResult::new(UnknownType::create(false).0)),
        EvalFlags::None,
    );
}

// analyzer/typedDicts.ts:1058
/// TS defaults: recursionCount = 0.
pub(crate) fn get_typed_dict_members_for_class_recursive(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    entries: P<TypedDictEntries>,
    recursion_count: u32,
) {
    assert!(ClassType::is_typed_dict_class(class_type));
    if recursion_count > MAX_TYPE_RECURSION_COUNT {
        return;
    }
    let recursion_count = recursion_count + 1;

    let base_classes = class_type.d().shared.get().base_classes.borrow().clone();
    for base_class_type in base_classes.iter().copied() {
        if is_instantiable_class(base_class_type)
            && ClassType::is_typed_dict_class(ClassType(base_class_type))
        {
            let specialized_base_class_type = partially_specialize_type(
                base_class_type,
                class_type,
                evaluator.get_type_class_type(),
                None,
            );
            assert!(is_class(specialized_base_class_type));

            // Recursively gather keys from parent classes. Don't report any errors
            // in these cases because they will be reported within that class.
            get_typed_dict_members_for_class_recursive(
                evaluator,
                ClassType(specialized_base_class_type),
                entries,
                recursion_count,
            );
        }
    }

    let solution = build_solution_from_specialized_class(class_type);

    if ClassType::is_typed_dict_marked_closed(class_type) {
        *entries.extra_items.borrow_mut() = Some(TypedDictEntry {
            value_type: NeverType::create_never().0,
            is_read_only: false,
            is_required: false,
            is_provided: false,
        });
    } else if let Some(extra_items_expr) = class_type
        .d()
        .shared
        .get()
        .typed_dict_extra_items_expr
        .get()
    {
        let extra_items_type_result = evaluator.get_type_of_expression_expecting_type(
            extra_items_expr,
            Some(&ExpectedTypeOptions {
                allow_read_only: Some(true),
                ..Default::default()
            }),
        );

        *entries.extra_items.borrow_mut() = Some(TypedDictEntry {
            value_type: convert_to_instance(extra_items_type_result.type_.get(), true),
            is_read_only: extra_items_type_result.is_read_only.unwrap_or(false),
            is_required: false,
            is_provided: true,
        });
    }

    // Add any new typed dict entries from this class.
    ClassType::get_symbol_table(class_type).for_each(|symbol, name| {
        if !symbol.is_ignored_for_protocol_match() {
            // Only variables (not functions, classes, etc.) are considered.
            let last_decl = get_last_typed_declaration_for_symbol(symbol);

            if let Some(last_decl) = last_decl
                && last_decl.type_ == DeclarationType::Variable
            {
                let mut value_type = evaluator.get_effective_type_of_symbol(symbol);
                value_type =
                    apply_solved_type_vars(value_type, &solution, &ApplyTypeVarOptions::default());

                let mut is_required = !ClassType::is_can_omit_dict_values(class_type);
                let mut is_read_only = false;

                if is_required_typed_dict_variable(evaluator, symbol) {
                    is_required = true;
                } else if is_not_required_typed_dict_variable(evaluator, symbol) {
                    is_required = false;
                }

                if is_read_only_typed_dict_variable(evaluator, symbol) {
                    is_read_only = true;
                }

                let td_entry = TypedDictEntry {
                    value_type,
                    is_read_only,
                    is_required,
                    is_provided: false,
                };

                entries
                    .known_items
                    .borrow_mut()
                    .insert(name.to_string(), td_entry);
            }
        }
    });
}

// analyzer/typedDicts.ts:1144
pub fn get_effective_extra_items_entry_type(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
) -> TypedDictEntry {
    assert!(ClassType::is_typed_dict_class(class_type));

    // Missing entries in a non-closed TypedDict class are implicitly typed as
    // ReadOnly[NotRequired[object]].
    if !ClassType::is_typed_dict_marked_closed(class_type) {
        return TypedDictEntry {
            value_type: evaluator.get_object_type(),
            is_read_only: true,
            is_required: false,
            is_provided: false,
        };
    }

    let cached_extra_items = class_type
        .d()
        .shared
        .get()
        .typed_dict_entries
        .get()
        .and_then(|cached| cached.extra_items.borrow().clone());
    if let Some(cached_extra_items) = cached_extra_items {
        return cached_extra_items;
    }

    TypedDictEntry {
        value_type: NeverType::create_never().0,
        is_read_only: true,
        is_required: false,
        is_provided: false,
    }
}

// analyzer/typedDicts.ts:1170
/// TS defaults: recursionCount = 0.
pub fn assign_typed_dict_to_typed_dict(
    evaluator: &TypeEvaluator,
    dest_type: ClassType,
    src_type: ClassType,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    flags: AssignTypeFlags,
    recursion_count: u32,
) -> bool {
    let mut types_are_consistent = true;
    let dest_entries = get_typed_dict_members_for_class(evaluator, dest_type, false);
    let src_entries =
        get_typed_dict_members_for_class(evaluator, src_type, /* allowNarrowed */ true);
    let src_extra_items = src_entries.extra_items.borrow().clone();
    let extra_src_entries = match src_extra_items {
        Some(extra_items) => extra_items,
        None => get_effective_extra_items_entry_type(evaluator, src_type),
    };

    let dest_known_items: Vec<(String, TypedDictEntry)> = dest_entries
        .known_items
        .borrow()
        .iter()
        .map(|(name, entry)| (name.clone(), entry.clone()))
        .collect();
    for (name, dest_entry) in dest_known_items {
        // If we've already determined that the types are inconsistent and
        // the caller isn't interested in detailed diagnostics, skip the remainder.
        if !types_are_consistent && diag.is_none() {
            continue;
        }

        let src_entry = src_entries.known_items.borrow().get(&name).cloned();
        match src_entry {
            None => {
                if dest_entry.is_required || !dest_entry.is_read_only {
                    if let Some(diag) = diag {
                        diag.create_addendum().add_message(
                            LocAddendum::typed_dict_field_missing().format(&[
                                ("name", &name),
                                (
                                    "type",
                                    &evaluator.print_type(
                                        ClassType::clone_as_instance(src_type, true).0,
                                        None,
                                    ),
                                ),
                            ]),
                        );
                    }
                    types_are_consistent = false;
                } else if is_class_instance(extra_src_entries.value_type) {
                    let sub_diag = diag.map(|diag| diag.create_addendum());
                    if !evaluator.assign_type(
                        dest_entry.value_type,
                        extra_src_entries.value_type,
                        sub_diag.map(|sub_diag| sub_diag.create_addendum()),
                        constraints,
                        flags,
                        recursion_count,
                    ) {
                        if let Some(sub_diag) = sub_diag {
                            sub_diag.add_message(
                                LocAddendum::member_type_mismatch().format(&[("name", &name)]),
                            );
                        }
                        types_are_consistent = false;
                    }
                }
            }
            Some(src_entry) => {
                if dest_entry.is_required != src_entry.is_required && !dest_entry.is_read_only {
                    let message = if dest_entry.is_required {
                        LocAddendum::typed_dict_field_required()
                    } else {
                        LocAddendum::typed_dict_field_not_required()
                    };
                    if let Some(diag) = diag {
                        diag.create_addendum().add_message(message.format(&[
                            ("name", &name),
                            (
                                "type",
                                &evaluator.print_type(
                                    ClassType::clone_as_instance(dest_type, true).0,
                                    None,
                                ),
                            ),
                        ]));
                    }
                    types_are_consistent = false;
                }

                if !dest_entry.is_read_only && src_entry.is_read_only {
                    if let Some(diag) = diag {
                        diag.create_addendum().add_message(
                            LocAddendum::typed_dict_field_not_read_only().format(&[
                                ("name", &name),
                                (
                                    "type",
                                    &evaluator.print_type(
                                        ClassType::clone_as_instance(dest_type, true).0,
                                        None,
                                    ),
                                ),
                            ]),
                        );
                    }
                    types_are_consistent = false;
                }

                let sub_diag = diag.map(|diag| diag.create_addendum());

                if !evaluator.assign_type(
                    dest_entry.value_type,
                    src_entry.value_type,
                    sub_diag.map(|sub_diag| sub_diag.create_addendum()),
                    constraints,
                    if dest_entry.is_read_only {
                        flags
                    } else {
                        flags | AssignTypeFlags::Invariant
                    },
                    recursion_count,
                ) {
                    if let Some(sub_diag) = sub_diag {
                        sub_diag.add_message(
                            LocAddendum::member_type_mismatch().format(&[("name", &name)]),
                        );
                    }
                    types_are_consistent = false;
                }
            }
        }
    }

    // If the types are not consistent and the caller isn't interested
    // in detailed diagnostics, don't do additional work.
    if !types_are_consistent && diag.is_none() {
        return false;
    }

    // If the destination TypedDict is closed, check any extra entries in the source
    // TypedDict to ensure that they don't violate the "extra items" type.
    if ClassType::is_typed_dict_effectively_closed(dest_type) {
        let dest_extra_items = dest_entries.extra_items.borrow().clone();
        let extra_dest_entries = match dest_extra_items.clone() {
            Some(extra_items) => extra_items,
            None => get_effective_extra_items_entry_type(evaluator, dest_type),
        };

        let src_known_items: Vec<(String, TypedDictEntry)> = src_entries
            .known_items
            .borrow()
            .iter()
            .map(|(name, entry)| (name.clone(), entry.clone()))
            .collect();
        for (name, src_entry) in src_known_items {
            // Have we already checked this item in the loop above?
            if dest_entries.known_items.borrow().contains_key(&name) {
                continue;
            }

            match &dest_extra_items {
                None => {
                    let sub_diag = diag.map(|diag| diag.create_addendum());
                    if let Some(sub_diag) = sub_diag {
                        sub_diag.add_message(
                            LocAddendum::typed_dict_extra_field_not_allowed().format(&[
                                ("name", &name),
                                (
                                    "type",
                                    &evaluator.print_type(
                                        ClassType::clone_as_instance(dest_type, true).0,
                                        None,
                                    ),
                                ),
                            ]),
                        );
                    }
                    types_are_consistent = false;
                }
                Some(dest_extra_items) => {
                    if src_entry.is_required && !dest_extra_items.is_read_only {
                        if let Some(diag) = diag {
                            diag.create_addendum().add_message(
                                LocAddendum::typed_dict_field_not_required().format(&[
                                    ("name", &name),
                                    (
                                        "type",
                                        &evaluator.print_type(
                                            ClassType::clone_as_instance(dest_type, true).0,
                                            None,
                                        ),
                                    ),
                                ]),
                            );
                        }
                        types_are_consistent = false;
                    }

                    let sub_diag = diag.map(|diag| diag.create_addendum());

                    if !evaluator.assign_type(
                        dest_extra_items.value_type,
                        src_entry.value_type,
                        sub_diag.map(|sub_diag| sub_diag.create_addendum()),
                        constraints,
                        if dest_extra_items.is_read_only {
                            flags
                        } else {
                            flags | AssignTypeFlags::Invariant
                        },
                        recursion_count,
                    ) {
                        if let Some(sub_diag) = sub_diag {
                            sub_diag.add_message(
                                LocAddendum::typed_dict_extra_field_type_mismatch().format(&[
                                    ("name", &name),
                                    (
                                        "type",
                                        &evaluator.print_type(
                                            ClassType::clone_as_instance(dest_type, true).0,
                                            None,
                                        ),
                                    ),
                                ]),
                            );
                        }
                        types_are_consistent = false;
                    } else if !dest_extra_items.is_read_only && src_entry.is_read_only {
                        if let Some(diag) = diag {
                            diag.create_addendum().add_message(
                                LocAddendum::typed_dict_field_not_read_only().format(&[
                                    ("name", &name),
                                    (
                                        "type",
                                        &evaluator.print_type(
                                            ClassType::clone_as_instance(src_type, true).0,
                                            None,
                                        ),
                                    ),
                                ]),
                            );
                        }
                        types_are_consistent = false;
                    }
                }
            }
        }

        let sub_diag = diag.map(|diag| diag.create_addendum());
        if !evaluator.assign_type(
            extra_dest_entries.value_type,
            extra_src_entries.value_type,
            sub_diag.map(|sub_diag| sub_diag.create_addendum()),
            constraints,
            if extra_dest_entries.is_read_only {
                flags
            } else {
                flags | AssignTypeFlags::Invariant
            },
            recursion_count,
        ) {
            if let Some(sub_diag) = sub_diag {
                sub_diag.add_message(
                    LocAddendum::typed_dict_extra_field_type_mismatch().format(&[
                        ("name", "extra_items"),
                        (
                            "type",
                            &evaluator
                                .print_type(ClassType::clone_as_instance(src_type, true).0, None),
                        ),
                    ]),
                );
            }
            types_are_consistent = false;
        } else if !extra_dest_entries.is_read_only && extra_src_entries.is_read_only {
            if let Some(diag) = diag {
                diag.create_addendum().add_message(
                    LocAddendum::typed_dict_field_not_read_only().format(&[
                        ("name", "extra_items"),
                        (
                            "type",
                            &evaluator
                                .print_type(ClassType::clone_as_instance(dest_type, true).0, None),
                        ),
                    ]),
                );
            }
            types_are_consistent = false;
        }
    }

    types_are_consistent
}

// analyzer/typedDicts.ts:1367
// Determines whether the specified keys and values can be assigned to
// a typed dictionary class. The caller should have already validated
// that the class is indeed a typed dict. If the types are compatible,
// the typed dict class or a narrowed form of the class is returned.
// Narrowing is possible when not-required keys are provided. If the
// types are not compatible, the function returns undefined.
pub fn assign_to_typed_dict(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    key_types: &[TypeResultWithNode],
    value_types: &[TypeResultWithNode],
    diag_addendum: Option<P<DiagnosticAddendum>>,
) -> Option<ClassType> {
    assert!(is_class_instance(class_type.0));
    assert!(ClassType::is_typed_dict_class(class_type));
    assert!(key_types.len() == value_types.len());

    let mut is_match = true;
    let mut narrowed_entries: JsMap<String, TypedDictEntry> = JsMap::default();

    let mut constraints: Option<P<ConstraintTracker>> = None;
    let mut generic_class_type = class_type;

    let has_type_params = !class_type.d().shared.get().type_params.borrow().is_empty();
    if has_type_params {
        constraints = Some(ConstraintTracker::new());

        // Create a generic (nonspecialized version) of the class.
        let has_type_args = class_type.d().priv_.borrow().type_args.is_some();
        if has_type_args {
            generic_class_type = ClassType::specialize(
                class_type, /* typeArgs */ None, None, false, None, None,
            );
        }
    }

    let td_entries = get_typed_dict_members_for_class(evaluator, generic_class_type, false);

    for (index, key_type_result) in key_types.iter().enumerate() {
        let key_type = key_type_result.type_;
        if !is_class_instance(key_type)
            || !ClassType::is_built_in(ClassType(key_type), Some(&["str"]))
            || !is_literal_type(ClassType(key_type))
        {
            is_match = false;
        } else {
            let literal_value = ClassType(key_type).d().priv_.borrow().literal_value.clone();
            let key_value = match literal_value {
                Some(LiteralValue::String(value)) => value.to_string_lossy(),
                _ => unreachable!("a str literal holds a string"),
            };
            let symbol_entry = td_entries.known_items.borrow().get(&key_value).cloned();

            match symbol_entry {
                None => {
                    let extra_items = td_entries.extra_items.borrow().clone();
                    if let Some(extra_items) = extra_items {
                        let sub_diag = diag_addendum.map(|diag| diag.create_addendum());
                        if !evaluator.assign_type(
                            extra_items.value_type,
                            value_types[index].type_,
                            sub_diag.map(|sub_diag| sub_diag.create_addendum()),
                            constraints,
                            AssignTypeFlags::RetainLiteralsForTypeVar,
                            0,
                        ) {
                            if let Some(sub_diag) = sub_diag {
                                sub_diag.add_message(
                                    LocAddendum::typed_dict_field_type_mismatch().format(&[
                                        ("name", "extra_items"),
                                        (
                                            "type",
                                            &evaluator.print_type(value_types[index].type_, None),
                                        ),
                                    ]),
                                );

                                sub_diag.add_text_range(key_type_result.node.text_range());
                            }
                            is_match = false;
                        }
                    } else {
                        // The provided key name doesn't exist.
                        is_match = false;
                        if let Some(diag_addendum) = diag_addendum {
                            let sub_diag = diag_addendum.create_addendum();
                            sub_diag.add_message(LocAddendum::typed_dict_field_undefined().format(
                                &[
                                    ("name", &key_value),
                                    (
                                        "type",
                                        &evaluator.print_type(
                                            ClassType::clone_as_instance(class_type, true).0,
                                            None,
                                        ),
                                    ),
                                ],
                            ));

                            sub_diag.add_text_range(key_type_result.node.text_range());
                        }
                    }
                }
                Some(symbol_entry) => {
                    // Can we assign the value to the declared type?
                    let sub_diag = diag_addendum.map(|diag| diag.create_addendum());
                    if !evaluator.assign_type(
                        symbol_entry.value_type,
                        value_types[index].type_,
                        sub_diag.map(|sub_diag| sub_diag.create_addendum()),
                        constraints,
                        AssignTypeFlags::RetainLiteralsForTypeVar,
                        0,
                    ) {
                        if let Some(sub_diag) = sub_diag {
                            sub_diag.add_message(
                                LocAddendum::typed_dict_field_type_mismatch().format(&[
                                    ("name", &key_value),
                                    (
                                        "type",
                                        &evaluator.print_type(value_types[index].type_, None),
                                    ),
                                ]),
                            );

                            sub_diag.add_text_range(key_type_result.node.text_range());
                        }
                        is_match = false;
                    }

                    if !symbol_entry.is_required {
                        narrowed_entries.insert(
                            key_value.clone(),
                            TypedDictEntry {
                                value_type: value_types[index].type_,
                                is_read_only: value_types[index].is_read_only.unwrap_or(false),
                                is_required: false,
                                is_provided: true,
                            },
                        );
                    }

                    if let Some(entry) = td_entries.known_items.borrow_mut().get_mut(&key_value) {
                        entry.is_provided = true;
                    }
                }
            }
        }
    }

    if !is_match {
        return None;
    }

    // See if any required keys are missing.
    let td_known_items: Vec<(String, TypedDictEntry)> = td_entries
        .known_items
        .borrow()
        .iter()
        .map(|(name, entry)| (name.clone(), entry.clone()))
        .collect();
    for (name, entry) in td_known_items {
        if entry.is_required && !entry.is_provided {
            if let Some(diag_addendum) = diag_addendum {
                diag_addendum.add_message(LocAddendum::typed_dict_field_required().format(&[
                    ("name", &name),
                    ("type", &evaluator.print_type(class_type.0, None)),
                ]));
            }
            is_match = false;
        }
    }

    if !is_match {
        return None;
    }

    let specialized_class_type = match constraints {
        Some(constraints) => ClassType(evaluator.solve_and_apply_constraints(
            generic_class_type.0,
            constraints,
            None,
            None,
        )),
        None => class_type,
    };

    if narrowed_entries.is_empty() {
        Some(specialized_class_type)
    } else {
        Some(ClassType::clone_for_narrowed_typed_dict_entries(
            specialized_class_type,
            Some(narrowed_entries),
        ))
    }
}

// analyzer/typedDicts.ts:1513
pub fn get_type_of_indexed_typed_dict(
    evaluator: &TypeEvaluator,
    node: IndexNode,
    base_type: ClassType,
    usage: &EvaluatorUsage,
) -> Option<P<TypeResult>> {
    let items = node.d().items.borrow().clone();
    if items.len() != 1 {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::type_args_mismatch_one()
                .format(&[("received", &number_to_string(items.len() as f64))]),
            node.0,
            None,
        );
        return Some(P::new_eval(TypeResult::new(UnknownType::create(false).0)));
    }

    // Look for subscript types that are not supported by TypedDict.
    if node.d().trailing_comma.get()
        || items[0].d().name.get().is_some()
        || items[0].d().arg_category.get() != ArgCategory::Simple
    {
        return None;
    }

    let entries = get_typed_dict_members_for_class(
        evaluator,
        base_type,
        /* allowNarrowed */ usage.method == "get",
    );

    let index_type_result =
        evaluator.get_type_of_expression(items[0].d().value_expr.get(), EvalFlags::None, None);
    let index_type = index_type_result.type_.get();
    let mut diag = DiagnosticAddendum::new();
    let mut all_diags_involve_not_required_keys = true;

    let resulting_type = map_subtypes(
        index_type,
        &mut |subtype| {
            if is_any_or_unknown(subtype) {
                return Some(subtype);
            }

            if is_class_instance(subtype)
                && ClassType::is_built_in(ClassType(subtype), Some(&["str"]))
            {
                let literal_value = ClassType(subtype).d().priv_.borrow().literal_value.clone();
                let Some(literal_value) = literal_value else {
                    // If it's a plain str with no literal value, we can't
                    // make any determination about the resulting type.
                    return Some(UnknownType::create(false).0);
                };

                // Look up the entry in the typed dict to get its type.
                let entry_name = match literal_value {
                    LiteralValue::String(value) => value.to_string_lossy(),
                    _ => unreachable!("a str literal holds a string"),
                };
                let known_entry = entries.known_items.borrow().get(&entry_name).cloned();
                let entry = match known_entry {
                    Some(known_entry) => Some(known_entry),
                    None => entries.extra_items.borrow().clone(),
                };
                let entry = match entry {
                    Some(entry) if !is_never(entry.value_type) => entry,
                    _ => {
                        diag.add_message(LocAddendum::key_undefined().format(&[
                            ("name", &entry_name),
                            ("type", &evaluator.print_type(base_type.0, None)),
                        ]));
                        all_diags_involve_not_required_keys = false;
                        return Some(UnknownType::create(false).0);
                    }
                };
                if !(entry.is_required || entry.is_provided) && usage.method == "get" {
                    diag.add_message(LocAddendum::key_not_required().format(&[
                        ("name", &entry_name),
                        ("type", &evaluator.print_type(base_type.0, None)),
                    ]));
                } else if entry.is_read_only && usage.method != "get" {
                    diag.add_message(LocAddendum::key_read_only().format(&[
                        ("name", &entry_name),
                        ("type", &evaluator.print_type(base_type.0, None)),
                    ]));
                }

                if usage.method == "set" {
                    let set_type = match usage.set_type {
                        Some(set_type) => set_type.type_.get(),
                        None => AnyType::create(false).0,
                    };
                    if !evaluator.assign_type(
                        entry.value_type,
                        set_type,
                        Some(diag),
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        all_diags_involve_not_required_keys = false;
                    }
                } else if usage.method == "del" && entry.is_required {
                    diag.add_message(
                        LocAddendum::key_required_deleted().format(&[("name", &entry_name)]),
                    );
                    all_diags_involve_not_required_keys = false;
                }

                return Some(entry.value_type);
            }

            diag.add_message(
                LocAddendum::type_not_string_literal()
                    .format(&[("type", &evaluator.print_type(subtype, None))]),
            );
            all_diags_involve_not_required_keys = false;
            Some(UnknownType::create(false).0)
        },
        None,
    );

    // If we have an "expected type" diagnostic addendum (used for assignments),
    // use that rather than the local diagnostic information because it will
    // be more informative.
    if let Some(set_expected_type_diag) = usage.set_expected_type_diag
        && !diag.is_empty()
        && !set_expected_type_diag.is_empty()
    {
        diag = set_expected_type_diag;
    }

    if !diag.is_empty() {
        let typed_dict_diag = if usage.method == "set" {
            LocMessage::typed_dict_set()
        } else if usage.method == "del" {
            LocMessage::typed_dict_delete()
        } else {
            LocMessage::typed_dict_access()
        };

        evaluator.add_diagnostic(
            if all_diags_involve_not_required_keys {
                DiagnosticRule::reportTypedDictNotRequiredAccess
            } else {
                DiagnosticRule::reportGeneralTypeIssues
            },
            &(typed_dict_diag
                + &diag.get_string(
                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                )),
            node.0,
            None,
        );
    }

    Some(P::new_eval(TypeResult {
        is_incomplete: Cell::new(Some(index_type_result.is_incomplete.get() == Some(true))),
        ..TypeResult::new(resulting_type)
    }))
}

// analyzer/typedDicts.ts:1632
// If the specified type has a non-required key, this method marks the
// key as present.
pub fn narrow_for_key_assignment(class_type: ClassType, key: &str) -> ClassType {
    // We should never be called if the classType is not a TypedDict or if typedDictEntries
    // is empty, but this can theoretically happen in the presence of certain circular
    // dependencies.
    if !ClassType::is_typed_dict_class(class_type) {
        return class_type;
    }
    let Some(typed_dict_entries) = class_type.d().shared.get().typed_dict_entries.get() else {
        return class_type;
    };

    let td_entry = typed_dict_entries.known_items.borrow().get(key).cloned();
    let Some(td_entry) = td_entry else {
        return class_type;
    };
    if td_entry.is_required {
        return class_type;
    }

    let narrowed_td_entry = class_type
        .d()
        .priv_
        .borrow()
        .cold().typed_dict_narrowed_entries
        .as_ref()
        .and_then(|narrowed_entries| narrowed_entries.get(key).cloned());
    if narrowed_td_entry.is_some_and(|narrowed_td_entry| narrowed_td_entry.is_provided) {
        return class_type;
    }

    let mut narrowed_entries = class_type
        .d()
        .priv_
        .borrow()
        .cold().typed_dict_narrowed_entries
        .clone()
        .unwrap_or_default();
    narrowed_entries.insert(
        key.to_string(),
        TypedDictEntry {
            is_provided: true,
            is_required: false,
            is_read_only: td_entry.is_read_only,
            value_type: td_entry.value_type,
        },
    );

    ClassType::clone_for_narrowed_typed_dict_entries(class_type, Some(narrowed_entries))
}

// analyzer/typedDicts.ts:1663
pub(crate) fn is_required_typed_dict_variable(
    evaluator: &TypeEvaluator,
    symbol: P<Symbol>,
) -> bool {
    symbol.get_declarations().iter().any(|decl| {
        if decl.type_ != DeclarationType::Variable {
            return false;
        }
        let Some(type_annotation_node) = decl
            .variable()
            .and_then(|variable| variable.type_annotation_node.get())
        else {
            return false;
        };

        let annotated_type = evaluator.get_type_of_expression_expecting_type(
            type_annotation_node,
            Some(&ExpectedTypeOptions {
                allow_final: Some(true),
                allow_required: Some(true),
                allow_read_only: Some(true),
                ..Default::default()
            }),
        );

        annotated_type.is_required.unwrap_or(false)
    })
}

